#!/usr/bin/env python3
"""Run from project root: python3 fix_complete.py"""
import base64, os, sys
if not os.path.exists("app"):
    print("ERROR: run from project root (where app/ exists)"); sys.exit(1)

# Binary assets (carousel slides)
BINARY = {
    "public/about/01_cover.png": "",
    "public/about/02_problem.png": "",
    "public/about/03_broken.png": "",
    "public/about/04_approach.png": "",
    "public/about/05_pipeline.png": "",
    "public/about/06_genesis.png": "",
    "public/about/07_verticals.png": "",
    "public/about/08_cta.png": "",
}
for path, enc in BINARY.items():
    d = os.path.dirname(path)
    if d: os.makedirs(d, exist_ok=True)
    open(path, "wb").write(base64.b64decode(enc))
    print(f"WRITTEN  {path}  ({os.path.getsize(path)//1024}KB)")

# Text files (code)
TEXT = {
    "lib/vos/userTokenStore.ts": "",
    "lib/vos/userLoanStore.ts": "",
    "lib/vos/commands.ts": "",
    "app/about/page.tsx": "",
    "app/terminal/page.tsx": "",
}
for path, enc in TEXT.items():
    d = os.path.dirname(path)
    if d: os.makedirs(d, exist_ok=True)
    content = base64.b64decode(enc).decode("utf-8")
    open(path, "w", encoding="utf-8", newline="\n").write(content)
    print(f"WRITTEN  {path}  ({len(content.splitlines())} lines)")

print("""
COMPLETE DEPLOY

Three things shipped:

  1. /about page with the 8-slide carousel
     Public URL: abraxas-app.vercel.app/about
     Slides in /public/about/ — same images as Instagram carousel

  2. Real green logo in terminal nav
     /icon-48.png now renders in nav (was just ◈ text)
     + ABOUT link added next to DASHBOARD

  3. Six new VOS commands — actual tokenize/borrow lifecycle:
     tokenize <id> [supply]   Mint tokens against VERIFIED asset
     holdings                 Show your token mints
     borrow <id> <amount>     Open USDC loan against collateral (60% LTV)
     repay <loan_id> [amt]    Repay full or partial
     loans                    List your loans
     oracle <id>              Live valuation feed (with drift)
     attest <id> <type>       Submit attestation (title/insurance/audit/etc)

Full VC demo flow now works end-to-end:
  /terminal → submit asset → /dashboard simulate to VERIFIED →
  /terminal → tokenize USR-XXXXXX → borrow USR-XXXXXX 50000 →
  loans → repay LN-XXXXXX 50000 → loan closed

Run:
  npm run build
  git add -A
  git commit -m \"feat: /about page, real logo in nav, tokenize+borrow+repay+oracle+attest commands\"
  git push origin main
""")
